/* Generated by deployment/build_membership_i18n.py; edit the JSON dictionaries. */
export const membershipLocales = {"en":{"notice":{"title":"Before you join","subtitle":"Understand AUTOLINK membership, vehicle sourcing, supplier verification and account rules before you subscribe."},"faq":{"membership":{"title":"Membership service","items":[{"question":"What do I get with membership?","answer":"Depending on your plan, AUTOLINK membership gives you access to member vehicle information and quotations, supplier profiles and contact details, saved vehicles and other sourcing tools. The benefits of each plan are those shown on the purchase page."},{"question":"When does my membership start?","answer":"Your membership period starts when payment succeeds and membership is activated. You can see the expiry date in My Membership in your account."},{"question":"Will my membership renew automatically?","answer":"AUTOLINK currently uses manual renewal. When a paid period ends, you may buy membership again if you wish. We will not charge you for another period without your express confirmation."},{"question":"What if membership prices change later?","answer":"A later price change does not affect the period you have already paid for. If you buy another period, the price shown at that time applies."},{"question":"Can I get a refund?","answer":"AUTOLINK membership is a digital service, and some features may be available immediately after activation. Refund eligibility depends on actual use, payment status, purchase time and applicable rules. Contact support if you were charged twice, charged in error, or paid successfully but membership was not activated. The refund policy sets out the detailed rules."},{"question":"Will my account be deleted when membership expires?","answer":"No. Your AUTOLINK account remains, but member-only features may become unavailable when membership expires. You may buy membership again later."}]},"purchase":{"title":"Vehicle sourcing","items":[{"question":"How do I buy after unlocking a supplier?","answer":"Once unlocked, you can view the contact details the supplier has made available and confirm the model, configuration, price, stock, lead time, trade terms, payment method and export details directly with them. A purchase is governed by the final quotation, purchase contract or sales contract agreed by buyer and seller."},{"question":"Is the price shown the final transaction price?","answer":"Not necessarily. Vehicle prices on AUTOLINK are sourcing references. The final price may depend on model, configuration, colour, quantity, stock, exchange rates, manufacturer policy, export port, logistics costs and market conditions. Ask the supplier for a current formal quotation before purchasing."},{"question":"What happens when a quotation expires?","answer":"The supplier may need to reconfirm the price. An expired quotation may be hidden or marked expired. The expiry of a particular vehicle quotation does not end your membership."},{"question":"Is stock information updated in real time?","answer":"Not necessarily. Stock can change because of other purchases, dealer transfers, manufacturer policies, export arrangements or model-year changes. Confirm actual availability with the supplier again before payment."},{"question":"Can every vehicle be exported to my country?","answer":"No. Import rules, emissions standards, vehicle certification, steering-side requirements, age limits, taxes and model approvals vary by destination. Check the rules of your destination country before purchasing."},{"question":"Are vehicle specifications completely accurate?","answer":"AUTOLINK works to maintain vehicle specifications, but the same model can differ by market, year and version. The final specification should be confirmed against the supplier's specification sheet, VIN information and purchase contract."}]},"supplier":{"title":"Suppliers","items":[{"question":"What is a Verified Supplier?","answer":"Under platform rules, AUTOLINK may check some suppliers' company names, registration details, business licences, contact details, basic business records and resource information. Suppliers completing the relevant checks may display a Verified Supplier label."},{"question":"Does verification mean AUTOLINK guarantees the transaction?","answer":"No. Verification means only that the platform checked certain company or resource information available at the time. It is not a guarantee of creditworthiness, stock, prices, performance, vehicle quality, payment safety, logistics timing or the final transaction outcome."},{"question":"What if I cannot reach a supplier?","answer":"If a supplier does not respond for an extended period, contact details no longer work, or vehicle information substantially differs from the listing after you unlock them, you can report this to AUTOLINK. We may review the supplier's information or take account measures as appropriate."},{"question":"What if I find a fraudulent supplier?","answer":"Report the concern through the platform or contact support. Include the supplier name, vehicle link, messages, quotation and other evidence where possible. AUTOLINK may review, restrict or remove a suspected account under platform rules."}]},"transaction":{"title":"Transactions and payments","items":[{"question":"Does AUTOLINK receive payment for vehicles?","answer":"The current AUTOLINK membership service does not collect vehicle purchase funds or hold them in escrow. Buyers and suppliers normally settle vehicle payments directly under their purchase contract. Unless a specific service page expressly says otherwise, do not send vehicle purchase funds to AUTOLINK's membership payment account."},{"question":"Is the membership fee a vehicle deposit?","answer":"No. It pays only for platform membership. It is not a vehicle deposit, vehicle payment, supplier security deposit, logistics or customs fee, or vehicle prepayment. Paying for membership does not automatically create a vehicle order."},{"question":"Does AUTOLINK charge a vehicle transaction commission?","answer":"AUTOLINK currently charges primarily for membership. Unless a service clearly states otherwise, viewing vehicles or contacting suppliers does not automatically create a vehicle transaction commission. Fees for any future sourcing agency, export, inspection, logistics or other added services will be explained before use."},{"question":"Can I buy a car directly on AUTOLINK?","answer":"AUTOLINK currently connects vehicle trade information and supply-chain resources. Contact Supplier, Get Quote and Send Enquiry help buyers connect with suppliers; using them does not complete a purchase. A formal transaction depends on the contract signed by buyer and seller."},{"question":"What if a transaction is disputed?","answer":"Vehicle purchase contracts are generally between buyer and supplier, so disputes should first be handled under their contract. AUTOLINK may help review accounts, contact suppliers or address platform violations where appropriate, but does not assume either party's contractual obligations unless expressly agreed."}]},"account":{"title":"Accounts and data","items":[{"question":"Can several people share one membership account?","answer":"An AUTOLINK membership is generally for the registered account holder or authorised staff within the registered company. Selling, renting or widely sharing an account, or using automation to scrape platform data in bulk, is prohibited."},{"question":"Can I export supplier contact details in bulk?","answer":"You may view and save supplier information needed for sourcing within the limits allowed by the platform. Without AUTOLINK's permission, you may not scrape, bulk export, resell or publicly distribute its supplier database, or use platform information to build a competing database."},{"question":"Will my details be shared with suppliers?","answer":"When you send an enquiry, contact a supplier or request a quotation, AUTOLINK may share information needed to answer your sourcing request with that supplier, such as your name, company, country or region, email, phone, WhatsApp and purchase requirements. The privacy policy explains the processing in more detail."},{"question":"Is AUTOLINK a car dealer?","answer":"AUTOLINK is a vehicle trade information and supply-chain connection platform. Unless a particular page expressly identifies AUTOLINK as the seller, it is not the seller of the vehicles shown. The seller is the company named as seller in the purchase contract."}]}},"policies":{"terms":"Terms of Service","membershipTerms":"Membership Terms","privacy":"Privacy Policy","refund":"Refund Policy"},"application":{"cta":"Apply now","enterpriseCta":"Ask about Enterprise","title":"Apply for membership","selected":"Selected plan","message":"Online payment is not available yet. Email AUTOLINK with your selected plan and account email. We will contact you about the next steps. No charge or membership activation happens on this page.","send":"Send application email","emailLabel":"Contact email","note":"Your email app will open. The request is sent only when you send the email."}},"zh-CN":{"notice":{"title":"开通前须知","subtitle":"了解 AUTOLINK 会员服务范围、车辆采购规则、供应商核验方式及账户使用规则。"},"faq":{"membership":{"title":"会员服务","items":[{"question":"开通会员后可以获得什么？","answer":"开通 AUTOLINK 会员后，根据对应会员等级，可使用平台提供的会员专属功能，包括查看会员车辆信息、会员报价、供应商资料、供应商联系方式、收藏车辆及其他采购相关功能。不同会员等级的具体权益，以购买页面实际展示内容为准。"},{"question":"会员什么时候开始计算？","answer":"会员有效期从支付成功并成功开通会员资格后开始计算。具体到期时间可在“个人中心－我的会员”中查看。"},{"question":"会员会自动续费吗？","answer":"当前 AUTOLINK 会员默认采用到期后主动续费方式。会员到期后，用户可以根据需要重新购买。平台不会在未经用户明确确认的情况下自动扣取下一周期会员费用。"},{"question":"会员价格以后调整怎么办？","answer":"已经支付完成的当前会员周期不会受到后续价格调整影响。用户下一次重新购买会员时，以当时页面显示的会员价格为准。"},{"question":"会员可以退款吗？","answer":"AUTOLINK 会员属于数字服务。由于部分会员功能在开通后即可立即使用，退款资格将根据实际使用情况、支付状态、购买时间及适用规则进行判断。如发生重复扣款、系统错误扣款或支付成功但会员未正常开通，可联系客服进行核查。具体规则以退款政策为准。"},{"question":"会员到期后账户会被删除吗？","answer":"不会。会员到期不会删除 AUTOLINK 账户，但部分会员专属功能将在会员失效后暂时无法继续使用。用户可以之后随时重新开通会员。"}]},"purchase":{"title":"车辆采购","items":[{"question":"解锁供应商后如何采购？","answer":"解锁供应商后，用户可以查看对应供应商开放的联系方式，并与供应商进一步确认车辆型号、配置、价格、库存、交期、贸易方式、付款方式及出口相关信息。正式采购应以买卖双方最终确认的报价单、采购合同或销售合同为准。"},{"question":"平台显示的价格是不是最终成交价？","answer":"不一定。AUTOLINK 页面中的车辆价格主要用于采购参考。实际成交价格可能受到车辆型号、配置、颜色、采购数量、库存、汇率、厂家政策、出口港口、物流费用及市场行情等因素影响。正式采购前，请向供应商获取最新正式报价。"},{"question":"报价过期后怎么办？","answer":"车辆报价超过有效期后，供应商可能需要重新确认价格。过期报价可能被系统隐藏或标记为已过期。会员身份不会因为某一个车辆报价过期而失效。"},{"question":"库存信息是不是实时库存？","answer":"不一定。汽车库存可能因为其他客户采购、经销商调拨、厂家政策、出口安排、年款切换等因素随时变化。付款前应再次向供应商确认实际库存。"},{"question":"车辆是否一定可以出口到我的国家？","answer":"不一定。不同国家和地区可能存在不同的汽车进口政策、排放标准、车辆认证要求、左右舵要求、年份限制、税费政策及车型准入规则。采购前应自行确认目的国相关政策。"},{"question":"车辆参数是否完全准确？","answer":"AUTOLINK 会尽力维护车辆参数信息，但同一车型在不同国家、年份和版本之间可能存在差异。最终配置应以供应商提供的车辆配置单、VIN 信息和正式采购合同为准。"}]},"supplier":{"title":"供应商","items":[{"question":"什么是“已核验供应商”？","answer":"AUTOLINK 可能根据平台规则，对部分供应商提供的企业名称、企业注册信息、营业执照、联系方式、基础经营资料及相关资源信息进行核验。完成对应核验流程的供应商可能显示“已核验供应商”标识。"},{"question":"核验是否代表 AUTOLINK 为交易担保？","answer":"不代表。供应商核验仅说明平台根据当时能够获得的信息，对部分企业或资源资料进行了检查。核验不代表 AUTOLINK 对供应商信用、库存、价格、履约、车辆质量、付款安全、物流时间或最终交易结果提供担保。"},{"question":"供应商联系不上怎么办？","answer":"如果会员解锁供应商后出现长时间未回复、联系方式失效、车辆信息与页面严重不符等情况，可以向 AUTOLINK 提交反馈。平台可根据情况核查相关供应商资料或采取账号管理措施。"},{"question":"发现虚假供应商怎么办？","answer":"用户可以通过平台举报功能或联系客服提交相关信息。建议同时提供供应商名称、车辆链接、聊天记录、报价单及其他相关证明材料。AUTOLINK 可根据平台规则对涉嫌违规账号进行审核、限制或删除。"}]},"transaction":{"title":"交易与付款","items":[{"question":"AUTOLINK 会参与车辆付款吗？","answer":"当前 AUTOLINK 会员服务不包含车辆交易代收款或资金托管服务。车辆采购款通常由买家与供应商根据双方正式采购合同直接结算。除非某项服务页面明确说明，请勿将车辆采购款支付至 AUTOLINK 的会员收费账户。"},{"question":"会员费是不是车辆订金？","answer":"不是。AUTOLINK 会员费仅用于购买平台会员服务，不属于车辆订金、车辆采购款、供应商保证金、物流费用、报关费用或车辆预付款。支付会员费不会自动产生任何车辆采购订单。"},{"question":"AUTOLINK 是否收取车辆交易佣金？","answer":"目前 AUTOLINK 的主要收费模式为会员服务费。除非某项服务另有明确说明，用户查看车辆、联系供应商不会自动产生车辆交易佣金。如未来新增采购代理、出口服务、验车、物流或其他增值服务，对应收费标准将在用户使用前单独说明。"},{"question":"我可以直接在 AUTOLINK 下单买车吗？","answer":"AUTOLINK 当前主要提供汽车贸易信息连接及供应链资源匹配服务。页面中的“联系供应商”“获取报价”“发送询盘”等功能用于帮助买家与供应商建立联系，并不代表已经完成车辆购买。正式交易以买卖双方签订的合同为准。"},{"question":"交易发生纠纷怎么办？","answer":"车辆采购合同原则上由买家与供应商之间签订，因此交易纠纷首先应按照双方合同约定处理。AUTOLINK 可以根据具体情况协助核查账号、联系供应商或处理平台违规行为，但除非另有明确约定，平台不代替交易任何一方承担合同责任。"}]},"account":{"title":"账户与数据","items":[{"question":"会员账号可以多人共用吗？","answer":"AUTOLINK 会员原则上仅供注册账户本人或注册企业内部授权人员使用。禁止出售、出租、大规模共享会员账号，以及通过自动化程序批量抓取平台数据。"},{"question":"供应商联系方式可以批量导出吗？","answer":"用户可在平台允许范围内查看和保存采购所需的供应商信息。未经 AUTOLINK 授权，不得批量抓取、批量导出、转售、公开传播供应商数据库或利用平台信息建立竞争数据库。"},{"question":"我的资料会提供给供应商吗？","answer":"当用户主动发送询盘、联系供应商或请求报价时，为帮助供应商回复采购需求，AUTOLINK 可能向对应供应商提供完成询盘所必要的信息，例如姓名、公司名称、国家或地区、Email、电话、WhatsApp 及采购需求。具体数据处理方式以隐私政策为准。"},{"question":"AUTOLINK 是汽车经销商吗？","answer":"AUTOLINK 是汽车贸易信息和供应链连接平台。除非具体页面明确说明 AUTOLINK 为实际销售主体，否则平台不是相关车辆的卖方。最终车辆销售主体以采购合同中列明的卖方公司为准。"}]}},"policies":{"terms":"服务条款","membershipTerms":"会员服务条款","privacy":"隐私政策","refund":"退款政策"},"application":{"cta":"立即开通","enterpriseCta":"咨询企业会员","title":"申请开通会员","selected":"所选方案","message":"线上付款暂未开放。请将所选方案和注册邮箱发给 AUTOLINK，我们会联系你说明后续步骤。此页面不会扣款，也不会直接开通会员。","send":"发送开通申请邮件","emailLabel":"联系邮箱","note":"将打开你的邮件程序；你发送邮件后，申请才会送达。"}},"ar":{"notice":{"title":"ما يجب معرفته قبل الاشتراك","subtitle":"تعرّف على خدمات عضوية AUTOLINK وقواعد شراء المركبات والتحقق من الموردين واستخدام الحساب."},"faq":{"membership":{"title":"خدمة العضوية","items":[{"question":"ما المزايا التي أحصل عليها بعد الاشتراك؟","answer":"وفقًا للخطة المختارة، تتيح العضوية الاطلاع على معلومات المركبات وعروض أسعار الأعضاء وملفات الموردين وبيانات التواصل معهم وحفظ المركبات وأدوات الشراء الأخرى. وتُحدَّد مزايا كل خطة بما هو معروض في صفحة الشراء."},{"question":"متى تبدأ مدة العضوية؟","answer":"تبدأ بعد نجاح الدفع وتفعيل العضوية. ويمكنك الاطلاع على تاريخ انتهائها في قسم «عضويتي» داخل حسابك."},{"question":"هل تُجدَّد العضوية تلقائيًا؟","answer":"تعتمد AUTOLINK حاليًا التجديد اليدوي. وبعد انتهاء الفترة المدفوعة يمكنك شراء العضوية مرة أخرى إذا رغبت. ولن تُخصم رسوم فترة جديدة من دون موافقتك الصريحة."},{"question":"ماذا لو تغيّرت الأسعار لاحقًا؟","answer":"لا يؤثر تغيير السعر في الفترة التي دفعت قيمتها بالفعل. وعند شراء فترة جديدة، يُطبَّق السعر المعروض وقت الشراء."},{"question":"هل يمكن استرداد الرسوم؟","answer":"عضوية AUTOLINK خدمة رقمية قد تتاح بعض مزاياها فور التفعيل. وتعتمد أهلية الاسترداد على الاستخدام الفعلي وحالة الدفع ووقت الشراء والقواعد السارية. تواصل مع الدعم عند الخصم المكرر أو الخاطئ أو نجاح الدفع من دون تفعيل العضوية. وتوضح سياسة الاسترداد التفاصيل."},{"question":"هل يُحذف حسابي عند انتهاء العضوية؟","answer":"لا. يبقى حسابك لدى AUTOLINK، لكن مزايا الأعضاء قد تتوقف مؤقتًا بعد انتهاء العضوية. ويمكنك الاشتراك مجددًا لاحقًا."}]},"purchase":{"title":"شراء المركبات","items":[{"question":"كيف أشتري بعد فتح بيانات المورد؟","answer":"يمكنك الاطلاع على بيانات التواصل التي أتاحها المورد والتأكد معه مباشرة من الطراز والمواصفات والسعر والمخزون وموعد التسليم وشروط التجارة وطريقة الدفع والتصدير. ويخضع الشراء لعرض السعر النهائي أو عقد الشراء أو البيع المتفق عليه بين الطرفين."},{"question":"هل السعر المعروض هو السعر النهائي؟","answer":"ليس بالضرورة. أسعار AUTOLINK مرجع أولي للشراء. وقد يتغير السعر النهائي بحسب الطراز والمواصفات واللون والكمية والمخزون وسعر الصرف وسياسة المصنّع وميناء التصدير وتكاليف النقل والسوق. اطلب عرض سعر رسميًا محدّثًا قبل الشراء."},{"question":"ماذا يحدث عند انتهاء صلاحية عرض السعر؟","answer":"قد يحتاج المورد إلى تأكيد السعر من جديد، وقد يُخفى العرض المنتهي أو يُوسم بأنه منتهي الصلاحية. انتهاء عرض لمركبة معينة لا يُنهي عضويتك."},{"question":"هل بيانات المخزون آنية؟","answer":"ليس بالضرورة. فقد يتغير المخزون بسبب مشتريات أخرى أو نقل المركبات بين الوكلاء أو سياسات المصنّع أو ترتيبات التصدير أو تغيّر سنة الطراز. أكّد التوافر الفعلي مع المورد قبل الدفع."},{"question":"هل يمكن تصدير كل مركبة إلى بلدي؟","answer":"لا. تختلف قواعد الاستيراد والانبعاثات واعتماد المركبات ومتطلبات جهة المقود وحدود العمر والضرائب والسماح بالطرازات بين البلدان. تحقّق من قواعد بلد الوجهة قبل الشراء."},{"question":"هل مواصفات المركبات دقيقة تمامًا؟","answer":"تسعى AUTOLINK إلى تحديث المواصفات، لكن الطراز نفسه قد يختلف باختلاف السوق والسنة والفئة. أكّد المواصفات النهائية من ورقة مواصفات المورد وبيانات VIN وعقد الشراء."}]},"supplier":{"title":"الموردون","items":[{"question":"ما معنى «مورد تم التحقق منه»؟","answer":"قد تتحقق AUTOLINK، وفق قواعدها، من أسماء بعض الشركات وبيانات تسجيلها ورخصها التجارية ووسائل التواصل ومعلومات نشاطها ومواردها. وقد يظهر وسم «مورد تم التحقق منه» لمن أكمل الفحوص المطلوبة."},{"question":"هل يعني التحقق أن AUTOLINK تضمن الصفقة؟","answer":"لا. يعني فقط فحص بعض المعلومات المتاحة وقت التحقق. ولا يشكل ضمانًا لملاءة المورد أو المخزون أو السعر أو التنفيذ أو جودة المركبة أو أمان الدفع أو مدة الشحن أو نتيجة الصفقة."},{"question":"ماذا لو تعذّر التواصل مع المورد؟","answer":"بعد فتح بياناته، يمكنك إبلاغ AUTOLINK إذا طال غياب الرد أو تعطلت بيانات الاتصال أو اختلفت معلومات المركبة اختلافًا كبيرًا عن الإعلان. وقد تراجع المنصة بيانات المورد أو تتخذ إجراءات بشأن حسابه حسب الحالة."},{"question":"ماذا لو وجدت موردًا محتالًا؟","answer":"أبلغ عنه عبر المنصة أو الدعم، وأرفق إن أمكن اسم المورد ورابط المركبة والمحادثات وعرض السعر والأدلة الأخرى. ويجوز لـ AUTOLINK مراجعة الحساب المشتبه به أو تقييده أو حذفه وفق قواعد المنصة."}]},"transaction":{"title":"المعاملات والمدفوعات","items":[{"question":"هل تستلم AUTOLINK ثمن المركبات؟","answer":"لا تشمل خدمة العضوية الحالية تحصيل ثمن المركبات أو حفظه في حساب ضمان. وعادةً ما يسوّي المشتري والمورد المدفوعات مباشرةً بموجب عقدهما. ما لم تذكر صفحة خدمة محددة خلاف ذلك صراحةً، فلا ترسل ثمن المركبة إلى حساب رسوم عضوية AUTOLINK."},{"question":"هل رسوم العضوية عربون للمركبة؟","answer":"لا. فهي مقابل خدمة العضوية فقط، وليست عربونًا أو ثمنًا للمركبة أو ضمانًا للمورد أو رسوم نقل أو جمارك أو دفعة مقدمة. ولا ينشئ دفع العضوية طلب شراء مركبة تلقائيًا."},{"question":"هل تتقاضى AUTOLINK عمولة على بيع المركبات؟","answer":"تعتمد إيرادات AUTOLINK حاليًا أساسًا على رسوم العضوية. وما لم يُذكر خلاف ذلك، فإن مشاهدة المركبات أو التواصل مع المورد لا ينشئ عمولة تلقائيًا. وستُوضَّح رسوم أي خدمات مستقبلية للشراء أو التصدير أو الفحص أو النقل قبل استخدامها."},{"question":"هل أستطيع شراء سيارة مباشرة عبر AUTOLINK؟","answer":"تربط AUTOLINK حاليًا معلومات تجارة السيارات وموارد سلسلة التوريد. وتساعد أدوات التواصل وطلب عرض السعر وإرسال الاستفسار على الاتصال بالمورد؛ ولا تُتم الشراء. ويستند البيع الرسمي إلى عقد المشتري والبائع."},{"question":"ماذا يحدث إذا نشأ نزاع حول الصفقة؟","answer":"يُبرم عقد شراء المركبة عادةً بين المشتري والمورد، لذا يُعالج النزاع أولًا وفق عقدهما. وقد تساعد AUTOLINK في مراجعة الحسابات أو التواصل مع المورد أو معالجة مخالفات المنصة، لكنها لا تتحمل التزامات أي طرف التعاقدية ما لم يُتفق صراحةً على غير ذلك."}]},"account":{"title":"الحساب والبيانات","items":[{"question":"هل يمكن لعدة أشخاص استخدام حساب عضوية واحد؟","answer":"العضوية مخصصة عمومًا لصاحب الحساب المسجّل أو الموظفين المخوّلين داخل الشركة المسجّلة. ويُحظر بيع الحساب أو تأجيره أو مشاركته على نطاق واسع أو استخدام أدوات آلية لجمع بيانات المنصة بكميات كبيرة."},{"question":"هل يمكن تصدير بيانات اتصال الموردين بالجملة؟","answer":"يمكنك الاطلاع على معلومات الموردين اللازمة للشراء وحفظها ضمن حدود المنصة. ومن دون إذن AUTOLINK، يُحظر جمع قاعدة الموردين أو تصديرها بالجملة أو إعادة بيعها أو نشرها أو إنشاء قاعدة منافسة اعتمادًا عليها."},{"question":"هل ستُشارك بياناتي مع الموردين؟","answer":"عند إرسال استفسار أو التواصل مع مورد أو طلب سعر، قد تشارك AUTOLINK معه البيانات اللازمة للرد، مثل الاسم والشركة والبلد أو المنطقة والبريد الإلكتروني والهاتف وWhatsApp واحتياجات الشراء. وتوضح سياسة الخصوصية التفاصيل."},{"question":"هل AUTOLINK تاجر سيارات؟","answer":"AUTOLINK منصة لمعلومات تجارة السيارات وربط سلاسل التوريد. ما لم تنص صفحة محددة صراحةً على أنها البائع، فهي ليست بائع المركبات المعروضة. والبائع هو الشركة المذكورة في عقد الشراء."}]}},"policies":{"terms":"شروط الخدمة","membershipTerms":"شروط العضوية","privacy":"سياسة الخصوصية","refund":"سياسة الاسترداد"},"application":{"cta":"قدّم طلب الانضمام","enterpriseCta":"استفسر عن عضوية الشركات","title":"طلب العضوية","selected":"الخطة المختارة","message":"الدفع عبر الموقع غير متاح بعد. راسل AUTOLINK مع الخطة المختارة وبريد حسابك الإلكتروني، وسنتواصل معك بشأن الخطوات التالية. لن تُخصم رسوم ولن تُفعّل العضوية من هذه الصفحة.","send":"إرسال طلب العضوية بالبريد","emailLabel":"البريد الإلكتروني للتواصل","note":"سيُفتح تطبيق البريد لديك، ولن يُرسل الطلب حتى ترسل الرسالة."}},"ru":{"notice":{"title":"Перед оформлением подписки","subtitle":"Узнайте об услугах AUTOLINK, покупке автомобилей, проверке поставщиков и правилах использования аккаунта."},"faq":{"membership":{"title":"Членство","items":[{"question":"Что даёт членство?","answer":"В зависимости от тарифа участник получает доступ к сведениям и предложениям по автомобилям для участников, профилям и контактам поставщиков, сохранённым автомобилям и другим инструментам закупки. Точный состав преимуществ указан на странице оплаты выбранного тарифа."},{"question":"Когда начинается срок членства?","answer":"После успешной оплаты и активации доступа. Дата окончания отображается в разделе «Моё членство» личного кабинета."},{"question":"Продлевается ли членство автоматически?","answer":"Сейчас AUTOLINK использует ручное продление. По окончании оплаченного периода вы можете снова купить членство по своему желанию. Без вашего явного подтверждения плата за следующий период не списывается."},{"question":"Что будет при изменении цен?","answer":"Изменение цены не влияет на уже оплаченный период. При следующей покупке применяется цена, показанная на странице в момент покупки."},{"question":"Можно ли получить возврат?","answer":"Членство AUTOLINK является цифровой услугой; отдельные функции доступны сразу после активации. Право на возврат зависит от фактического использования, статуса платежа, даты покупки и применимых правил. При двойном или ошибочном списании, а также при оплате без активации обратитесь в поддержку. Подробности изложены в политике возвратов."},{"question":"Удалят ли мой аккаунт после окончания членства?","answer":"Нет. Аккаунт AUTOLINK сохраняется, но функции для участников могут стать недоступны. Позже вы сможете снова приобрести членство."}]},"purchase":{"title":"Закупка автомобилей","items":[{"question":"Как купить автомобиль после открытия контактов поставщика?","answer":"Вы сможете увидеть опубликованные поставщиком контакты и напрямую уточнить модель, комплектацию, цену, наличие, срок поставки, торговые условия, порядок оплаты и экспорта. Покупка регулируется окончательным предложением или договором между покупателем и продавцом."},{"question":"Цена на сайте окончательная?","answer":"Не обязательно. Цены на AUTOLINK служат ориентиром для закупки. Итоговая цена зависит от модели, комплектации, цвета, количества, наличия, валютного курса, политики производителя, порта экспорта, логистики и рынка. До покупки запросите актуальное официальное предложение."},{"question":"Что делать, если срок предложения истёк?","answer":"Поставщику может потребоваться подтвердить цену заново. Просроченное предложение может быть скрыто или помечено как истёкшее. Это не прекращает ваше членство."},{"question":"Данные о наличии обновляются в реальном времени?","answer":"Не обязательно. Наличие меняется из-за покупок других клиентов, перемещения между дилерами, решений производителя, экспортных планов и смены модельного года. Повторно подтвердите фактическое наличие перед оплатой."},{"question":"Любой автомобиль можно вывезти в мою страну?","answer":"Нет. Правила импорта, нормы выбросов, сертификация, требования к расположению руля, возрастные ограничения, налоги и допуск моделей различаются по странам. Проверьте требования страны назначения до покупки."},{"question":"Все характеристики автомобиля абсолютно точны?","answer":"AUTOLINK старается поддерживать сведения в актуальном состоянии, но одна модель может различаться по рынку, году и версии. Окончательную комплектацию следует сверить со спецификацией поставщика, данными VIN и договором покупки."}]},"supplier":{"title":"Поставщики","items":[{"question":"Что означает «Проверенный поставщик»?","answer":"По правилам платформы AUTOLINK может проверять название компании, регистрационные данные, лицензию, контакты, основные сведения о деятельности и ресурсах некоторых поставщиков. После соответствующей проверки поставщик может получить отметку «Проверенный поставщик»."},{"question":"Проверка означает гарантию сделки от AUTOLINK?","answer":"Нет. Отметка означает лишь проверку отдельных данных, доступных на тот момент. Она не гарантирует надёжность поставщика, наличие, цену, исполнение, качество автомобиля, безопасность оплаты, сроки доставки или результат сделки."},{"question":"Что делать, если поставщик не выходит на связь?","answer":"После открытия контактов сообщите AUTOLINK о длительном отсутствии ответа, недействительных контактах или существенном несоответствии объявления. Платформа может проверить данные поставщика и при необходимости принять меры в отношении аккаунта."},{"question":"Что делать при обнаружении недобросовестного поставщика?","answer":"Подайте жалобу на платформе или обратитесь в поддержку. По возможности приложите название поставщика, ссылку на автомобиль, переписку, предложение и другие доказательства. AUTOLINK может проверить, ограничить или удалить подозреваемый аккаунт согласно правилам."}]},"transaction":{"title":"Сделки и платежи","items":[{"question":"AUTOLINK принимает оплату за автомобили?","answer":"Текущая услуга членства не включает приём средств за автомобили или их хранение на эскроу. Обычно покупатель и поставщик рассчитываются напрямую по договору. Если на странице конкретной услуги прямо не сказано иное, не перечисляйте деньги за автомобиль на счёт оплаты членства AUTOLINK."},{"question":"Членский взнос — это задаток за автомобиль?","answer":"Нет. Он оплачивает только доступ к сервису. Это не задаток или оплата автомобиля, не гарантийный взнос поставщику, не расходы на логистику или таможню и не предоплата. Оплата членства не создаёт заказ автомобиля автоматически."},{"question":"AUTOLINK взимает комиссию за сделки с автомобилями?","answer":"Сейчас основным источником оплаты AUTOLINK является членство. Если иное не объявлено отдельно, просмотр автомобилей или контакт с поставщиком не создаёт комиссию за сделку. Стоимость будущих услуг закупки, экспорта, осмотра, логистики и иных услуг будет сообщена до их использования."},{"question":"Можно ли купить автомобиль прямо на AUTOLINK?","answer":"Сейчас AUTOLINK связывает участников торговли и данные цепочки поставок. Кнопки связи с поставщиком, запроса цены и отправки запроса помогают установить контакт, но не завершают покупку. Сделка оформляется договором покупателя и продавца."},{"question":"Как решается спор по сделке?","answer":"Договор покупки обычно заключается между покупателем и поставщиком, поэтому спор сначала решается по этому договору. AUTOLINK может помочь проверить аккаунт, связаться с поставщиком или рассмотреть нарушение правил платформы, но не принимает на себя обязательства сторон без отдельного соглашения."}]},"account":{"title":"Аккаунт и данные","items":[{"question":"Можно ли пользоваться одним аккаунтом нескольким людям?","answer":"Членство предназначено для владельца аккаунта или уполномоченных сотрудников зарегистрированной компании. Продажа, аренда, массовое совместное использование аккаунта и автоматизированный массовый сбор данных запрещены."},{"question":"Можно ли массово выгружать контакты поставщиков?","answer":"Вы можете просматривать и сохранять нужные для закупки сведения в пределах правил платформы. Без разрешения AUTOLINK нельзя массово собирать или выгружать, перепродавать, публично распространять базу поставщиков либо создавать на её основе конкурирующую базу."},{"question":"Передаются ли мои данные поставщикам?","answer":"Когда вы отправляете запрос, связываетесь с поставщиком или запрашиваете цену, AUTOLINK может передать ему данные, необходимые для ответа: имя, компанию, страну или регион, email, телефон, WhatsApp и потребности закупки. Подробнее — в политике конфиденциальности."},{"question":"AUTOLINK — автомобильный дилер?","answer":"AUTOLINK — платформа торговой информации и связей в автомобильной цепочке поставок. Если на конкретной странице прямо не указано, что продавец — AUTOLINK, платформа не является продавцом автомобиля. Продавцом считается компания, указанная в договоре покупки."}]}},"policies":{"terms":"Условия использования","membershipTerms":"Условия членства","privacy":"Политика конфиденциальности","refund":"Политика возвратов"},"application":{"cta":"Подать заявку","enterpriseCta":"Узнать о корпоративном плане","title":"Заявка на членство","selected":"Выбранный план","message":"Оплата на сайте пока недоступна. Напишите AUTOLINK, указав выбранный план и адрес электронной почты аккаунта. Мы сообщим о дальнейших шагах. На этой странице оплата и активация не производятся.","send":"Отправить заявку по почте","emailLabel":"Контактный адрес","note":"Откроется почтовое приложение. Заявка будет отправлена только после отправки письма."}},"kk":{"notice":{"title":"Мүшелікке өтер алдында","subtitle":"AUTOLINK мүшелік қызметін, автокөлік сатып алу тәртібін, жеткізушілерді тексеруді және аккаунт ережелерін біліп алыңыз."},"faq":{"membership":{"title":"Мүшелік қызметі","items":[{"question":"Мүшелік қандай мүмкіндіктер береді?","answer":"Таңдалған жоспарға қарай мүшелерге арналған көлік мәліметтері мен бағалар, жеткізуші профилі мен байланыс деректері, сақталған көліктер және сатып алуға көмектесетін басқа құралдар қолжетімді болады. Әр жоспардың нақты артықшылықтары сатып алу бетінде көрсетіледі."},{"question":"Мүшелік мерзімі қашан басталады?","answer":"Төлем сәтті өтіп, мүшелік іске қосылғанда басталады. Аяқталу күні аккаунттағы «Менің мүшелігім» бөлімінде көрсетіледі."},{"question":"Мүшелік автоматты түрде ұзара ма?","answer":"Қазір AUTOLINK мүшелікті қолмен ұзартуды қолданады. Төленген мерзім біткен соң қаласаңыз, мүшелікті қайта сатып аласыз. Сіздің нақты келісіміңізсіз келесі мерзім үшін ақша алынбайды."},{"question":"Баға кейін өзгерсе не болады?","answer":"Кейінгі баға өзгерісі бұрын төленген мерзімге әсер етпейді. Қайта сатып алған кезде сол сәтте бетте көрсетілген баға қолданылады."},{"question":"Ақшаны қайтаруға бола ма?","answer":"AUTOLINK мүшелігі — цифрлық қызмет, кейбір функциялары іске қосылған бойда қолжетімді. Қайтару құқығы нақты пайдалануға, төлем күйіне, сатып алу уақытына және қолданылатын ережелерге байланысты. Қосарланған не қате төлемде немесе төлем өтіп, мүшелік қосылмаса, қолдау қызметіне жүгініңіз. Толық шарттар қайтару саясатында беріледі."},{"question":"Мүшелік біткенде аккаунтым жойыла ма?","answer":"Жоқ. AUTOLINK аккаунты сақталады, бірақ мүшелерге ғана арналған функциялар уақытша қолжетімсіз болуы мүмкін. Кейін мүшелікті қайта сатып ала аласыз."}]},"purchase":{"title":"Көлік сатып алу","items":[{"question":"Жеткізуші ашылғаннан кейін көлікті қалай сатып аламын?","answer":"Жеткізуші жариялаған байланыс деректерін көріп, модельді, жиынтықтаманы, бағаны, қорды, жеткізу мерзімін, сауда шарттарын, төлем мен экспорт жайын тікелей нақтылай аласыз. Сатып алу тараптар келіскен түпкілікті баға ұсынысына немесе сатып алу-сату шартына сүйенеді."},{"question":"Сайттағы баға түпкілікті мәміле бағасы ма?","answer":"Міндетті түрде емес. AUTOLINK бағалары сатып алуға бағдар ретінде беріледі. Түпкілікті баға модельге, жиынтықтамаға, түске, санға, қорға, валюта бағамына, өндіруші саясатына, экспорт портына, логистикаға және нарыққа тәуелді. Сатып алар алдында жаңа ресми баға ұсынысын сұраңыз."},{"question":"Баға ұсынысының мерзімі өтсе не болады?","answer":"Жеткізуші бағаны қайта растауы мүмкін. Мерзімі өткен ұсыныс жасырылуы немесе белгіленуі мүмкін. Бір ұсыныстың мерзімі өтуі мүшелікті тоқтатпайды."},{"question":"Қор туралы ақпарат нақты уақыттағы дерек пе?","answer":"Міндетті түрде емес. Басқа сатып алушылар, дилерлер арасындағы ауыстыру, өндіруші саясаты, экспорт жоспары және модель жылының ауысуы қорды өзгертуі мүмкін. Төлем алдында нақты бар-жоғын қайта тексеріңіз."},{"question":"Кез келген көлікті еліме экспорттауға бола ма?","answer":"Жоқ. Импорт ережелері, шығарындылар нормалары, сертификаттау, руль жағына қойылатын талаптар, жас шектеуі, салық және модельге рұқсат елге қарай өзгереді. Сатып алар алдында баратын елдің талаптарын тексеріңіз."},{"question":"Көлік сипаттамалары толық дәл ме?","answer":"AUTOLINK деректерді өзекті ұстауға тырысады, бірақ бір модель нарыққа, жылға және нұсқаға қарай өзгеруі мүмкін. Түпкілікті жиынтықтаманы жеткізушінің сипаттамасынан, VIN дерегінен және шарттан тексеріңіз."}]},"supplier":{"title":"Жеткізушілер","items":[{"question":"«Тексерілген жеткізуші» деген не?","answer":"AUTOLINK платформа ережелеріне сай кейбір жеткізушілердің компания атауын, тіркеу дерегін, кәсіпкерлік құжатын, байланысын, қызметі мен ресурстары туралы мәліметтерін тексере алады. Тиісті тексеруден өткендерге «Тексерілген жеткізуші» белгісі берілуі мүмкін."},{"question":"Тексеру AUTOLINK мәмілеге кепіл болады деген сөз бе?","answer":"Жоқ. Бұл тек сол кезде қолжетімді кейбір мәліметтердің қаралғанын білдіреді. Ол жеткізушінің сенімділігіне, қорға, бағаға, орындауға, көлік сапасына, төлем қауіпсіздігіне, логистика мерзіміне не мәміле нәтижесіне кепіл емес."},{"question":"Жеткізушімен байланыса алмасам не істеймін?","answer":"Байланысты ашқаннан кейін ұзақ жауап болмаса, деректер жарамсыз болса немесе көлік хабарландырудан елеулі өзгеше болса, AUTOLINK-ке хабарлаңыз. Платформа ақпаратты тексеріп, жағдайға қарай аккаунтқа шара қолдана алады."},{"question":"Жалған жеткізушіні байқасам не істеймін?","answer":"Платформа арқылы немесе қолдау қызметіне хабарлаңыз. Мүмкін болса, жеткізуші атауын, көлік сілтемесін, хаттарды, баға ұсынысын және басқа дәлелдерді жіберіңіз. AUTOLINK күмәнді аккаунтты ережелеріне сай тексеріп, шектеп немесе жоя алады."}]},"transaction":{"title":"Мәміле және төлем","items":[{"question":"AUTOLINK көлік ақысын қабылдай ма?","answer":"Қазіргі мүшелік қызметі көлік ақысын жинауды немесе эскроуда сақтауды қамтымайды. Әдетте сатып алушы мен жеткізуші өз шарты бойынша тікелей есеп айырысады. Белгілі бір қызмет бетінде басқаша нақты айтылмаса, көлік ақысын AUTOLINK мүшелік төлем шотына аудармаңыз."},{"question":"Мүшелік ақысы көліктің кепілақысы ма?","answer":"Жоқ. Ол тек платформа мүшелігін төлейді; көлік кепілақысы, көлік төлемі, жеткізуші кепілдігі, логистика не кеден шығыны немесе алдын ала төлем емес. Мүшелік төлемі көлік тапсырысын автоматты жасамайды."},{"question":"AUTOLINK көлік мәмілесінен комиссия ала ма?","answer":"Қазір AUTOLINK негізінен мүшелік ақысын алады. Бөлек көрсетілмесе, көлікті көру немесе жеткізушімен байланысу мәміле комиссиясын туғызбайды. Болашақ сатып алу агенті, экспорт, тексеру, логистика және басқа қосымша қызметтердің ақысы қолданар алдында хабарланады."},{"question":"AUTOLINK арқылы тікелей көлік сатып ала аламын ба?","answer":"Қазір AUTOLINK автомобиль саудасы туралы ақпарат пен жеткізу тізбегін байланыстырады. Жеткізушіге жазу, баға сұрау және сұраным жіберу сатып алуды аяқтамайды. Ресми мәміле сатып алушы мен сатушы шартына негізделеді."},{"question":"Мәміле бойынша дау туса не болады?","answer":"Көлік шарты әдетте сатып алушы мен жеткізуші арасында жасалады, сондықтан дау алдымен сол шарт бойынша шешіледі. AUTOLINK аккаунтты тексеруге, жеткізушімен байланысуға немесе платформа бұзушылығын қарауға көмектесе алады, бірақ нақты келісім болмаса, тараптардың шарттық міндетін өзіне алмайды."}]},"account":{"title":"Аккаунт және деректер","items":[{"question":"Бір мүшелік аккаунтын бірнеше адам қолдана ала ма?","answer":"Мүшелік негізінен тіркелген иесіне немесе сол компанияның уәкілетті қызметкерлеріне арналған. Аккаунтты сату, жалға беру, жаппай ортақ пайдалану және автоматтандырылған түрде деректерді көптеп жинау тыйым салынады."},{"question":"Жеткізуші байланыстарын жаппай экспорттауға бола ма?","answer":"Платформа рұқсат еткен шекте сатып алуға қажет ақпаратты көріп, сақтай аласыз. AUTOLINK рұқсатынсыз жеткізушілер базасын жаппай жинауға, экспорттауға, сатуға, жариялауға немесе одан бәсекелес база жасауға болмайды."},{"question":"Менің деректерім жеткізушіге беріле ме?","answer":"Сұраным жібергенде, жеткізушіге жазғанда не баға сұрағанда, AUTOLINK жауап беру үшін қажет аты-жөніңізді, компанияны, елді не өңірді, email, телефонды, WhatsApp-ты және сатып алу талабын сол жеткізушімен бөлісуі мүмкін. Толығырақ құпиялылық саясатында."},{"question":"AUTOLINK автодилер ме?","answer":"AUTOLINK — автомобиль саудасы туралы ақпарат және жеткізу тізбегін байланыстыру платформасы. Белгілі бір бетте AUTOLINK сатушы екені нақты жазылмаса, ол көрсетілген көліктің сатушысы емес. Сатушы — сатып алу шартында аталған компания."}]}},"policies":{"terms":"Қызмет көрсету шарттары","membershipTerms":"Мүшелік шарттары","privacy":"Құпиялылық саясаты","refund":"Ақшаны қайтару саясаты"},"application":{"cta":"Өтінім беру","enterpriseCta":"Корпоративтік жоспар туралы сұрау","title":"Мүшелікке өтінім","selected":"Таңдалған жоспар","message":"Сайтта төлем жасау әзірге қолжетімсіз. Таңдалған жоспарды және аккаунттың электрондық поштасын көрсетіп, AUTOLINK-ке хат жіберіңіз. Келесі қадамдар туралы хабарласамыз. Бұл бетте төлем алынбайды және мүшелік қосылмайды.","send":"Өтінімді электрондық поштамен жіберу","emailLabel":"Байланыс поштасы","note":"Пошта қолданбасы ашылады. Өтінім хатты жібергеннен кейін ғана жолданады."}},"uz":{"notice":{"title":"A’zo bo‘lishdan oldin","subtitle":"AUTOLINK a’zolik xizmati, avtomobil xaridi, yetkazib beruvchilarni tekshirish va hisob qoidalari bilan tanishing."},"faq":{"membership":{"title":"A’zolik xizmati","items":[{"question":"A’zolik qanday imkoniyatlar beradi?","answer":"Tanlangan rejaga qarab, a’zolar uchun avtomobil ma’lumotlari va narx takliflari, yetkazib beruvchi profili va aloqa ma’lumotlari, saqlangan avtomobillar hamda xaridga oid boshqa vositalardan foydalanasiz. Har bir rejaning aniq imtiyozlari xarid sahifasida ko‘rsatiladi."},{"question":"A’zolik muddati qachon boshlanadi?","answer":"To‘lov muvaffaqiyatli o‘tib, a’zolik faollashgan paytdan boshlanadi. Tugash sanasini hisobingizdagi «Mening a’zoligim» bo‘limida ko‘rasiz."},{"question":"A’zolik avtomatik uzaytiriladimi?","answer":"Hozir AUTOLINK qo‘lda uzaytirish tartibidan foydalanadi. To‘langan muddat tugagach, xohlasangiz a’zolikni qayta sotib olasiz. Sizning aniq roziligingizsiz keyingi davr uchun pul yechilmaydi."},{"question":"Narxlar keyin o‘zgarsa nima bo‘ladi?","answer":"Keyingi narx o‘zgarishi allaqachon to‘langan davrga ta’sir qilmaydi. Qayta xarid qilganda o‘sha vaqtda sahifada ko‘rsatilgan narx amal qiladi."},{"question":"Pulni qaytarib olish mumkinmi?","answer":"AUTOLINK a’zoligi raqamli xizmat bo‘lib, ayrim funksiyalar faollashishi bilan ishlaydi. Qaytarish huquqi haqiqiy foydalanish, to‘lov holati, xarid vaqti va amaldagi qoidalarga bog‘liq. Ikki marta yoki xato yechilgan pul, yoxud to‘lovdan keyin a’zolik yoqilmagan bo‘lsa, yordam xizmatiga murojaat qiling. Batafsil shartlar qaytarish siyosatida."},{"question":"A’zolik tugasa hisobim o‘chiriladimi?","answer":"Yo‘q. AUTOLINK hisobingiz saqlanadi, ammo a’zolarga xos funksiyalar vaqtincha ishlamasligi mumkin. Keyin yana a’zo bo‘lishingiz mumkin."}]},"purchase":{"title":"Avtomobil xaridi","items":[{"question":"Yetkazib beruvchi ochilgach qanday xarid qilaman?","answer":"U ochiq qilgan aloqa ma’lumotlarini ko‘rib, model, jihozlanish, narx, zaxira, yetkazish muddati, savdo shartlari, to‘lov usuli va eksport tafsilotlarini bevosita aniqlang. Xarid tomonlar kelishgan yakuniy narx taklifi yoki oldi-sotdi shartnomasiga asoslanadi."},{"question":"Sahifadagi narx yakuniy savdo narximi?","answer":"Har doim emas. AUTOLINK narxlari xarid uchun mo‘ljal hisoblanadi. Yakuniy narx model, jihozlanish, rang, miqdor, zaxira, valyuta kursi, ishlab chiqaruvchi siyosati, eksport porti, logistika va bozorga bog‘liq. Xariddan oldin yangi rasmiy taklif so‘rang."},{"question":"Narx taklifi muddati tugasa nima bo‘ladi?","answer":"Yetkazib beruvchi narxni qayta tasdiqlashi kerak bo‘lishi mumkin. Muddati o‘tgan taklif yashiriladi yoki belgilab qo‘yiladi. Bitta taklifning tugashi a’zolikni tugatmaydi."},{"question":"Zaxira ma’lumoti real vaqt rejimidami?","answer":"Har doim emas. Boshqa xaridlar, dilerlar o‘rtasidagi o‘tkazmalar, ishlab chiqaruvchi siyosati, eksport rejasi yoki model yili almashishi zaxirani o‘zgartiradi. To‘lovdan oldin mavjudligini yana tasdiqlang."},{"question":"Har bir avtomobilni mamlakatimga eksport qilsa bo‘ladimi?","answer":"Yo‘q. Import qoidalari, chiqindi me’yorlari, sertifikatlash, rul tomoni talablari, yosh cheklovi, soliqlar va modellarga ruxsat mamlakatga qarab farq qiladi. Xariddan oldin boradigan mamlakat qoidalarini tekshiring."},{"question":"Avtomobil xususiyatlari to‘liq aniqmi?","answer":"AUTOLINK ma’lumotni yangilab borishga intiladi, biroq bir model bozor, yil va versiyaga qarab farq qilishi mumkin. Yakuniy jihozlanishni yetkazib beruvchi hujjati, VIN ma’lumoti va xarid shartnomasi bilan tekshiring."}]},"supplier":{"title":"Yetkazib beruvchilar","items":[{"question":"«Tekshirilgan yetkazib beruvchi» nimani anglatadi?","answer":"AUTOLINK platforma qoidalariga ko‘ra ayrim yetkazib beruvchilarning kompaniya nomi, ro‘yxatga olish ma’lumoti, litsenziyasi, aloqasi, faoliyati va resurslari haqidagi hujjatlarni tekshirishi mumkin. Tegishli tekshiruvdan o‘tganlarga «Tekshirilgan yetkazib beruvchi» belgisi berilishi mumkin."},{"question":"Tekshiruv AUTOLINK bitimga kafolat beradi deganimi?","answer":"Yo‘q. Bu faqat o‘sha paytda mavjud ayrim ma’lumotlar ko‘rilganini bildiradi. U yetkazib beruvchining ishonchliligi, zaxirasi, narxi, shartnomani bajarishi, avtomobil sifati, to‘lov xavfsizligi, logistika muddati yoki bitim natijasiga kafolat emas."},{"question":"Yetkazib beruvchi javob bermasa nima qilaman?","answer":"Aloqa ochilgach uzoq vaqt javob bo‘lmasa, ma’lumotlar ishlamasa yoki e’londagi avtomobil ma’lumoti jiddiy farq qilsa, AUTOLINK-ga xabar bering. Platforma vaziyatga qarab ma’lumotlarni tekshirishi yoki hisobga chora ko‘rishi mumkin."},{"question":"Soxta yetkazib beruvchini topsam nima qilaman?","answer":"Platformada shikoyat yuboring yoki yordam xizmatiga yozing. Iloji bo‘lsa, nomi, avtomobil havolasi, yozishmalar, narx taklifi va boshqa dalillarni qo‘shing. AUTOLINK shubhali hisobni qoidalarga ko‘ra tekshirishi, cheklashi yoki o‘chirishi mumkin."}]},"transaction":{"title":"Bitim va to‘lovlar","items":[{"question":"AUTOLINK avtomobil pulini qabul qiladimi?","answer":"Hozirgi a’zolik xizmatiga avtomobil xaridi pulini yig‘ish yoki eskrouda saqlash kirmaydi. Odatda xaridor va yetkazib beruvchi o‘z shartnomasiga binoan bevosita hisob-kitob qiladi. Muayyan xizmat sahifasida aniq boshqacha yozilmasa, avtomobil pulini AUTOLINK a’zolik to‘lovi hisobiga yubormang."},{"question":"A’zolik badali avtomobil uchun zakalatmi?","answer":"Yo‘q. U faqat platforma a’zoligi uchun to‘lanadi; avtomobil zakalati yoki narxi, yetkazib beruvchi kafolati, logistika yoki bojxona xarajati yoxud oldindan to‘lov emas. A’zolik to‘lovi avtomobil buyurtmasini avtomatik yaratmaydi."},{"question":"AUTOLINK avtomobil bitimidan komissiya oladimi?","answer":"Hozir AUTOLINK asosan a’zolik badali oladi. Boshqacha aniq aytilmasa, avtomobilni ko‘rish yoki yetkazib beruvchiga murojaat qilish bitim komissiyasini keltirib chiqarmaydi. Kelajakdagi xarid agentligi, eksport, ko‘rik, logistika va boshqa xizmatlar narxi foydalanishdan oldin alohida ko‘rsatiladi."},{"question":"AUTOLINK-da bevosita avtomobil buyurtma qila olamanmi?","answer":"AUTOLINK hozir avtomobil savdosi ma’lumoti va ta’minot zanjiri resurslarini bog‘laydi. Yetkazib beruvchiga yozish, narx so‘rash yoki so‘rov yuborish xaridni yakunlamaydi. Rasmiy bitim xaridor va sotuvchi shartnomasiga asoslanadi."},{"question":"Bitim bo‘yicha nizo chiqsa nima bo‘ladi?","answer":"Avtomobil xarid shartnomasi odatda xaridor va yetkazib beruvchi o‘rtasida tuziladi; nizo avvalo shu shartnoma bo‘yicha hal qilinadi. AUTOLINK hisobni tekshirish, yetkazib beruvchi bilan bog‘lanish yoki platforma qoidabuzarligini ko‘rishga yordam berishi mumkin, ammo alohida kelishuvsiz tomonlar majburiyatini o‘z zimmasiga olmaydi."}]},"account":{"title":"Hisob va ma’lumotlar","items":[{"question":"Bitta a’zolik hisobidan bir necha kishi foydalana oladimi?","answer":"A’zolik asosan ro‘yxatdagi hisob egasi yoki shu korxonaning vakolatli xodimlari uchun. Hisobni sotish, ijaraga berish, ommaviy ulashish va avtomatik vositalar bilan ma’lumotni ko‘p miqdorda yig‘ish taqiqlanadi."},{"question":"Yetkazib beruvchilar aloqasini ommaviy eksport qilsam bo‘ladimi?","answer":"Platforma ruxsat bergan doirada xarid uchun kerakli ma’lumotni ko‘rib saqlashingiz mumkin. AUTOLINK ruxsatisiz bazani ommaviy yig‘ish yoki eksport qilish, qayta sotish, ochiq tarqatish yoki undan raqobatchi baza yaratish mumkin emas."},{"question":"Ma’lumotlarim yetkazib beruvchiga beriladimi?","answer":"So‘rov yuborsangiz, yetkazib beruvchiga yozsangiz yoki narx so‘rasangiz, AUTOLINK javob uchun zarur ism, kompaniya, mamlakat yoki hudud, email, telefon, WhatsApp va xarid talablarini tegishli yetkazib beruvchiga berishi mumkin. Tafsilotlar maxfiylik siyosatida."},{"question":"AUTOLINK avtomobil dilerimi?","answer":"AUTOLINK — avtomobil savdosi ma’lumoti va ta’minot zanjiri aloqalari platformasi. Muayyan sahifada AUTOLINK sotuvchi ekani aniq yozilmasa, u ko‘rsatilgan avtomobil sotuvchisi emas. Sotuvchi — xarid shartnomasida ko‘rsatilgan kompaniya."}]}},"policies":{"terms":"Xizmat shartlari","membershipTerms":"A’zolik shartlari","privacy":"Maxfiylik siyosati","refund":"Pulni qaytarish siyosati"},"application":{"cta":"Ariza yuborish","enterpriseCta":"Korporativ reja haqida so‘rash","title":"A’zolik uchun ariza","selected":"Tanlangan reja","message":"Saytda to‘lov hozircha mavjud emas. Tanlangan reja va akkauntingiz email manzilini ko‘rsatib, AUTOLINK’ga yozing. Keyingi qadamlar bo‘yicha siz bilan bog‘lanamiz. Bu sahifada to‘lov olinmaydi va a’zolik faollashtirilmaydi.","send":"Arizani email orqali yuborish","emailLabel":"Aloqa emaili","note":"Email ilovangiz ochiladi. Xatni yuborganingizdan keyingina ariza jo‘natiladi."}},"ko":{"notice":{"title":"가입 전 확인 사항","subtitle":"AUTOLINK 멤버십 서비스, 차량 구매, 공급업체 확인 및 계정 이용 규칙을 확인하세요."},"faq":{"membership":{"title":"멤버십 서비스","items":[{"question":"멤버십에 가입하면 무엇을 이용할 수 있나요?","answer":"선택한 요금제에 따라 회원 전용 차량 정보와 견적, 공급업체 프로필과 연락처, 차량 저장 및 기타 구매 지원 기능을 이용할 수 있습니다. 각 요금제의 구체적인 혜택은 구매 페이지에 표시된 내용에 따릅니다."},{"question":"멤버십 기간은 언제 시작되나요?","answer":"결제가 성공하고 멤버십이 활성화된 때부터 시작됩니다. 만료일은 계정의 ‘내 멤버십’에서 확인할 수 있습니다."},{"question":"멤버십이 자동 갱신되나요?","answer":"현재 AUTOLINK는 직접 갱신 방식을 사용합니다. 결제한 기간이 끝나면 원할 때 다시 구매할 수 있습니다. 명시적인 확인 없이 다음 기간의 요금을 자동 청구하지 않습니다."},{"question":"나중에 가격이 변경되면 어떻게 되나요?","answer":"이미 결제한 현재 기간에는 이후의 가격 변경이 적용되지 않습니다. 다음에 다시 구매할 때는 그 시점에 표시된 가격이 적용됩니다."},{"question":"환불받을 수 있나요?","answer":"AUTOLINK 멤버십은 활성화 직후 일부 기능을 사용할 수 있는 디지털 서비스입니다. 환불 가능 여부는 실제 이용 내역, 결제 상태, 구매 시점 및 적용 규정에 따라 판단합니다. 중복 또는 잘못된 결제, 결제 성공 후 미활성화가 발생하면 고객지원팀에 문의하세요. 자세한 기준은 환불 정책을 따릅니다."},{"question":"멤버십이 만료되면 계정이 삭제되나요?","answer":"아니요. AUTOLINK 계정은 유지되지만 회원 전용 기능은 이용할 수 없게 될 수 있습니다. 나중에 다시 멤버십을 구매할 수 있습니다."}]},"purchase":{"title":"차량 구매","items":[{"question":"공급업체를 잠금 해제한 후 어떻게 구매하나요?","answer":"공급업체가 공개한 연락처를 확인한 뒤 차종, 사양, 가격, 재고, 납기, 거래 조건, 결제 방법 및 수출 정보를 직접 확인하세요. 실제 구매는 구매자와 판매자가 최종 합의한 견적서 또는 매매계약서에 따릅니다."},{"question":"플랫폼에 표시된 가격이 최종 거래 가격인가요?","answer":"반드시 그렇지는 않습니다. AUTOLINK의 가격은 구매 참고용입니다. 최종 가격은 차종, 사양, 색상, 수량, 재고, 환율, 제조사 정책, 수출 항구, 물류비 및 시장 상황에 따라 달라질 수 있습니다. 구매 전에 최신 공식 견적을 요청하세요."},{"question":"견적 유효기간이 지나면 어떻게 되나요?","answer":"공급업체가 가격을 다시 확인해야 할 수 있습니다. 만료된 견적은 숨겨지거나 만료 표시가 붙을 수 있습니다. 특정 차량 견적의 만료로 멤버십이 종료되지는 않습니다."},{"question":"재고 정보는 실시간인가요?","answer":"반드시 그렇지는 않습니다. 다른 고객의 구매, 판매점 간 이동, 제조사 정책, 수출 일정 및 연식 변경으로 재고가 수시로 바뀔 수 있습니다. 결제 전에 실제 재고를 공급업체에 다시 확인하세요."},{"question":"모든 차량을 제 국가로 수출할 수 있나요?","answer":"아니요. 국가별로 수입 규정, 배출가스 기준, 차량 인증, 운전석 위치, 차량 연식 제한, 세금 및 차종 승인 요건이 다릅니다. 구매 전에 목적지 국가의 규정을 확인하세요."},{"question":"차량 제원은 완전히 정확한가요?","answer":"AUTOLINK는 정보를 정확하게 유지하려 노력하지만 같은 모델도 시장, 연식 및 트림에 따라 다를 수 있습니다. 최종 사양은 공급업체의 사양서, VIN 정보 및 구매 계약서로 확인하세요."}]},"supplier":{"title":"공급업체","items":[{"question":"‘확인된 공급업체’란 무엇인가요?","answer":"AUTOLINK는 플랫폼 규정에 따라 일부 공급업체의 회사명, 등록 정보, 사업자 서류, 연락처, 기본 영업 자료 및 공급 자원 정보를 확인할 수 있습니다. 해당 절차를 완료한 공급업체에는 ‘확인된 공급업체’ 표시가 붙을 수 있습니다."},{"question":"확인이 AUTOLINK의 거래 보증을 뜻하나요?","answer":"아니요. 당시 입수 가능한 일부 회사 또는 자원 정보를 확인했다는 뜻일 뿐입니다. 신용도, 재고, 가격, 계약 이행, 차량 품질, 결제 안전, 물류 시간 또는 최종 거래 결과를 보증하지 않습니다."},{"question":"공급업체와 연락이 닿지 않으면 어떻게 하나요?","answer":"잠금 해제 후 장기간 답변이 없거나 연락처가 유효하지 않거나 차량 정보가 게시 내용과 크게 다르면 AUTOLINK에 신고할 수 있습니다. 플랫폼은 상황에 따라 자료를 확인하거나 계정 조치를 취할 수 있습니다."},{"question":"허위 공급업체를 발견하면 어떻게 하나요?","answer":"플랫폼 신고 기능 또는 고객지원팀에 알려주세요. 가능하면 공급업체명, 차량 링크, 대화 기록, 견적서와 기타 증거를 제출하세요. AUTOLINK는 규정에 따라 의심 계정을 검토, 제한 또는 삭제할 수 있습니다."}]},"transaction":{"title":"거래 및 결제","items":[{"question":"AUTOLINK가 차량 대금을 받나요?","answer":"현재 멤버십 서비스에는 차량 구매 대금의 대리 수령이나 에스크로 보관이 포함되지 않습니다. 차량 대금은 일반적으로 구매자와 공급업체가 계약에 따라 직접 정산합니다. 특정 서비스 페이지에서 명시하지 않은 한 차량 대금을 AUTOLINK 멤버십 결제 계정으로 보내지 마세요."},{"question":"멤버십 요금이 차량 계약금인가요?","answer":"아니요. 플랫폼 멤버십 서비스 비용일 뿐이며 차량 계약금, 차량 대금, 공급업체 보증금, 물류비, 통관비 또는 차량 선금이 아닙니다. 멤버십 결제로 차량 주문이 자동 생성되지 않습니다."},{"question":"AUTOLINK가 차량 거래 수수료를 받나요?","answer":"현재 AUTOLINK의 주요 유료 서비스는 멤버십입니다. 별도 명시가 없다면 차량 조회나 공급업체 연락만으로 거래 수수료가 발생하지 않습니다. 향후 구매 대행, 수출, 검사, 물류 등 부가서비스의 요금은 이용 전에 별도로 안내합니다."},{"question":"AUTOLINK에서 직접 차를 주문할 수 있나요?","answer":"현재 AUTOLINK는 자동차 무역 정보와 공급망 연결 서비스를 제공합니다. 공급업체 연락, 견적 요청 및 문의 전송은 연결을 돕는 기능이며 구매 완료를 의미하지 않습니다. 정식 거래는 구매자와 판매자의 계약에 따릅니다."},{"question":"거래 분쟁이 발생하면 어떻게 하나요?","answer":"차량 구매 계약은 일반적으로 구매자와 공급업체 사이에 체결되므로 먼저 그 계약에 따라 처리해야 합니다. AUTOLINK는 상황에 따라 계정을 확인하거나 공급업체에 연락하거나 플랫폼 위반을 처리할 수 있지만, 별도 명시적 합의가 없으면 어느 당사자의 계약상 책임도 대신 지지 않습니다."}]},"account":{"title":"계정 및 데이터","items":[{"question":"여러 사람이 멤버십 계정을 함께 사용할 수 있나요?","answer":"원칙적으로 등록된 계정 소유자 또는 등록 기업 내 승인된 직원만 이용할 수 있습니다. 계정 판매, 임대, 대규모 공유와 자동화 도구를 이용한 플랫폼 데이터 대량 수집은 금지됩니다."},{"question":"공급업체 연락처를 대량 내보낼 수 있나요?","answer":"플랫폼이 허용하는 범위에서 구매에 필요한 정보를 조회하고 저장할 수 있습니다. AUTOLINK의 허가 없이 공급업체 데이터베이스를 대량 수집·내보내기·재판매·공개 배포하거나 플랫폼 정보로 경쟁 데이터베이스를 만들 수 없습니다."},{"question":"제 정보가 공급업체에 전달되나요?","answer":"문의, 공급업체 연락 또는 견적 요청 시 응답에 필요한 이름, 회사명, 국가·지역, 이메일, 전화번호, WhatsApp 및 구매 요구 사항을 해당 공급업체에 제공할 수 있습니다. 자세한 내용은 개인정보 처리방침을 확인하세요."},{"question":"AUTOLINK는 자동차 판매업체인가요?","answer":"AUTOLINK는 자동차 무역 정보와 공급망 연결 플랫폼입니다. 특정 페이지에서 AUTOLINK를 실제 판매자로 명시하지 않는 한 표시된 차량의 판매자가 아닙니다. 최종 판매자는 구매 계약서에 기재된 회사입니다."}]}},"policies":{"terms":"서비스 약관","membershipTerms":"멤버십 약관","privacy":"개인정보 처리방침","refund":"환불 정책"},"application":{"cta":"지금 신청하기","enterpriseCta":"기업 회원 문의","title":"회원 가입 신청","selected":"선택한 요금제","message":"온라인 결제는 아직 제공되지 않습니다. 선택한 요금제와 계정 이메일을 AUTOLINK에 보내 주세요. 다음 절차를 안내해 드리겠습니다. 이 페이지에서는 결제되거나 회원 권한이 활성화되지 않습니다.","send":"신청 이메일 보내기","emailLabel":"문의 이메일","note":"메일 앱이 열립니다. 이메일을 보내야 신청이 전달됩니다."}},"fr":{"notice":{"title":"À savoir avant d’adhérer","subtitle":"Comprenez les services membres d’AUTOLINK, l’achat de véhicules, la vérification des fournisseurs et les règles du compte."},"faq":{"membership":{"title":"Service d’adhésion","items":[{"question":"Quels avantages offre l’adhésion ?","answer":"Selon la formule choisie, vous pouvez accéder aux informations et devis réservés aux membres, aux profils et coordonnées des fournisseurs, aux véhicules enregistrés et à d’autres outils d’approvisionnement. Les avantages précis de chaque formule sont ceux indiqués sur la page d’achat."},{"question":"Quand mon adhésion commence-t-elle ?","answer":"Elle commence une fois le paiement réussi et l’accès membre activé. Sa date d’expiration figure dans « Mon adhésion » de votre compte."},{"question":"L’adhésion se renouvelle-t-elle automatiquement ?","answer":"AUTOLINK prévoit actuellement un renouvellement manuel. À l’expiration de la période payée, vous pouvez racheter une formule si vous le souhaitez. Aucun nouveau paiement ne sera prélevé sans votre confirmation expresse."},{"question":"Que se passe-t-il si les prix changent ?","answer":"Un changement ultérieur n’affecte pas la période déjà payée. Lors d’un nouvel achat, le prix affiché à ce moment-là s’applique."},{"question":"Puis-je obtenir un remboursement ?","answer":"L’adhésion AUTOLINK est un service numérique dont certaines fonctions peuvent être utilisables dès l’activation. L’éligibilité dépend de l’utilisation réelle, du paiement, de la date d’achat et des règles applicables. Contactez l’assistance en cas de double prélèvement, de prélèvement erroné ou de paiement réussi sans activation. La politique de remboursement précise les conditions."},{"question":"Mon compte sera-t-il supprimé à l’expiration ?","answer":"Non. Votre compte AUTOLINK demeure, mais les fonctions réservées aux membres peuvent devenir indisponibles. Vous pourrez adhérer de nouveau plus tard."}]},"purchase":{"title":"Achat de véhicules","items":[{"question":"Comment acheter après avoir débloqué un fournisseur ?","answer":"Vous pouvez consulter les coordonnées qu’il rend disponibles et confirmer directement le modèle, la configuration, le prix, le stock, le délai, les conditions commerciales, le paiement et l’exportation. L’achat est régi par le devis final ou le contrat conclu entre acheteur et vendeur."},{"question":"Le prix affiché est-il le prix final ?","answer":"Pas nécessairement. Les prix AUTOLINK sont indicatifs. Le prix final peut varier selon le modèle, les options, la couleur, la quantité, le stock, le taux de change, la politique du constructeur, le port d’exportation, la logistique et le marché. Demandez un devis officiel actualisé avant d’acheter."},{"question":"Que faire si un devis expire ?","answer":"Le fournisseur peut devoir reconfirmer le prix. Un devis expiré peut être masqué ou signalé comme tel. L’expiration d’un devis ne met pas fin à votre adhésion."},{"question":"Les stocks sont-ils mis à jour en temps réel ?","answer":"Pas nécessairement. Les achats d’autres clients, transferts entre concessionnaires, décisions du constructeur, expéditions et changements de millésime peuvent modifier le stock. Confirmez la disponibilité réelle avant de payer."},{"question":"Tous les véhicules peuvent-ils être exportés vers mon pays ?","answer":"Non. Les règles d’importation, normes d’émissions, homologations, exigences de conduite à droite ou à gauche, limites d’âge, taxes et autorisations de modèles varient selon le pays. Vérifiez les règles de destination avant d’acheter."},{"question":"Les caractéristiques des véhicules sont-elles parfaitement exactes ?","answer":"AUTOLINK s’efforce de les tenir à jour, mais un même modèle peut varier selon le marché, l’année et la version. Confirmez la configuration définitive à l’aide de la fiche du fournisseur, du VIN et du contrat d’achat."}]},"supplier":{"title":"Fournisseurs","items":[{"question":"Qu’est-ce qu’un « fournisseur vérifié » ?","answer":"Selon ses règles, AUTOLINK peut contrôler le nom, l’immatriculation, la licence commerciale, les coordonnées, les informations d’activité et les ressources de certains fournisseurs. Ceux qui terminent les contrôles requis peuvent porter la mention « Fournisseur vérifié »."},{"question":"Cette vérification garantit-elle la transaction ?","answer":"Non. Elle signifie seulement que certaines informations disponibles au moment du contrôle ont été examinées. Elle ne garantit ni la solvabilité, ni le stock, le prix, l’exécution, la qualité du véhicule, la sécurité du paiement, le délai logistique ou l’issue de la transaction."},{"question":"Que faire si un fournisseur ne répond pas ?","answer":"Après déblocage, signalez à AUTOLINK une absence prolongée de réponse, des coordonnées invalides ou de fortes différences avec l’annonce. La plateforme pourra vérifier les informations ou prendre des mesures sur le compte selon le cas."},{"question":"Que faire face à un fournisseur frauduleux ?","answer":"Signalez-le sur la plateforme ou à l’assistance, si possible avec son nom, le lien du véhicule, les échanges, le devis et les preuves. AUTOLINK peut examiner, limiter ou supprimer un compte suspect selon ses règles."}]},"transaction":{"title":"Transactions et paiements","items":[{"question":"AUTOLINK reçoit-il le paiement des véhicules ?","answer":"Le service d’adhésion actuel ne collecte pas les fonds d’achat des véhicules et ne les garde pas sous séquestre. Acheteur et fournisseur règlent normalement directement selon leur contrat. Sauf indication expresse d’un service précis, ne versez pas le prix d’un véhicule sur le compte destiné aux adhésions AUTOLINK."},{"question":"La cotisation est-elle un acompte sur véhicule ?","answer":"Non. Elle paie uniquement le service membre. Ce n’est ni un acompte ou paiement de véhicule, ni une garantie fournisseur, ni des frais logistiques ou douaniers, ni un prépaiement. L’adhésion ne crée pas automatiquement une commande."},{"question":"AUTOLINK prélève-t-il une commission sur les véhicules ?","answer":"Son modèle de revenus actuel repose principalement sur les adhésions. Sauf indication contraire, consulter un véhicule ou contacter un fournisseur ne crée pas automatiquement de commission. Les frais de futurs services d’achat, d’exportation, d’inspection, de logistique ou autres seront annoncés avant utilisation."},{"question":"Puis-je acheter directement une voiture sur AUTOLINK ?","answer":"AUTOLINK met actuellement en relation informations commerciales et ressources de la chaîne d’approvisionnement. Contacter un fournisseur, demander un devis ou envoyer une demande ne conclut pas un achat. La transaction formelle dépend du contrat entre acheteur et vendeur."},{"question":"Que faire en cas de litige commercial ?","answer":"Le contrat d’achat est généralement conclu entre acheteur et fournisseur ; le litige doit d’abord être traité selon ce contrat. AUTOLINK peut, selon le cas, examiner les comptes, contacter le fournisseur ou traiter une infraction sur la plateforme, sans assumer les obligations contractuelles d’une partie sauf accord exprès."}]},"account":{"title":"Compte et données","items":[{"question":"Plusieurs personnes peuvent-elles partager un compte membre ?","answer":"En principe, l’adhésion est réservée au titulaire inscrit ou au personnel autorisé de l’entreprise inscrite. La vente, la location, le partage massif du compte et l’extraction automatisée de données en masse sont interdits."},{"question":"Puis-je exporter en masse les coordonnées des fournisseurs ?","answer":"Vous pouvez consulter et conserver les informations nécessaires à vos achats dans les limites autorisées. Sans autorisation d’AUTOLINK, il est interdit de collecter ou exporter en masse, revendre, diffuser publiquement la base de fournisseurs ou créer une base concurrente à partir des données de la plateforme."},{"question":"Mes données seront-elles transmises aux fournisseurs ?","answer":"Lorsque vous envoyez une demande, contactez un fournisseur ou sollicitez un devis, AUTOLINK peut lui transmettre les informations nécessaires à la réponse : nom, entreprise, pays ou région, email, téléphone, WhatsApp et besoin d’achat. La politique de confidentialité détaille ce traitement."},{"question":"AUTOLINK est-il concessionnaire automobile ?","answer":"AUTOLINK est une plateforme d’information commerciale et de mise en relation dans la chaîne automobile. Sauf mention expresse indiquant qu’AUTOLINK est vendeur, la plateforme ne vend pas les véhicules présentés. Le vendeur est l’entreprise désignée dans le contrat d’achat."}]}},"policies":{"terms":"Conditions d’utilisation","membershipTerms":"Conditions d’adhésion","privacy":"Politique de confidentialité","refund":"Politique de remboursement"},"application":{"cta":"Faire une demande","enterpriseCta":"Contacter pour l’offre Entreprise","title":"Demande d’adhésion","selected":"Formule choisie","message":"Le paiement en ligne n’est pas encore disponible. Envoyez à AUTOLINK la formule choisie et l’adresse email de votre compte. Nous vous contacterons pour la suite. Aucun paiement ni activation n’a lieu sur cette page.","send":"Envoyer la demande par email","emailLabel":"Email de contact","note":"Votre application de messagerie s’ouvrira. La demande ne sera transmise qu’après l’envoi du message."}},"sw":{"notice":{"title":"Mambo ya kujua kabla ya kujiunga","subtitle":"Fahamu huduma za uanachama wa AUTOLINK, ununuzi wa magari, uhakiki wa wauzaji na sheria za akaunti."},"faq":{"membership":{"title":"Huduma ya uanachama","items":[{"question":"Uanachama unanipa manufaa gani?","answer":"Kulingana na mpango wako, unaweza kuona taarifa na bei za magari za wanachama, wasifu na mawasiliano ya wauzaji, kuhifadhi magari na kutumia zana nyingine za ununuzi. Manufaa mahususi ya kila mpango ni yale yanayoonyeshwa kwenye ukurasa wa ununuzi."},{"question":"Uanachama wangu unaanza lini?","answer":"Unaanza malipo yanapofanikiwa na uanachama kuamilishwa. Tarehe ya mwisho inaonekana kwenye ‘Uanachama Wangu’ ndani ya akaunti yako."},{"question":"Je, uanachama unasasishwa kiotomatiki?","answer":"Kwa sasa AUTOLINK hutumia usasishaji wa hiari unaofanywa na mwanachama. Kipindi ulicholipia kikiisha, unaweza kununua tena ukipenda. Hatutakata malipo ya kipindi kingine bila uthibitisho wako wa wazi."},{"question":"Bei zikibadilika baadaye itakuwaje?","answer":"Mabadiliko ya baadaye hayaathiri kipindi ambacho tayari umelipia. Ukinunua tena, bei iliyoonyeshwa wakati huo ndiyo itakayotumika."},{"question":"Je, ninaweza kurejeshewa fedha?","answer":"Uanachama wa AUTOLINK ni huduma ya kidijitali; baadhi ya vipengele vinaweza kutumika mara tu baada ya kuamilishwa. Haki ya kurejeshewa fedha hutegemea matumizi halisi, hali ya malipo, wakati wa ununuzi na kanuni husika. Wasiliana na usaidizi ukikatwa mara mbili, ukikatwa kimakosa au ukilipa bila uanachama kuamilishwa. Sera ya marejesho ina maelezo kamili."},{"question":"Akaunti yangu itafutwa uanachama ukiisha?","answer":"Hapana. Akaunti yako ya AUTOLINK itabaki, lakini huduma za wanachama zinaweza kusitishwa hadi ujiunge tena. Unaweza kununua uanachama baadaye."}]},"purchase":{"title":"Ununuzi wa magari","items":[{"question":"Nitanunuaje baada ya kufungua mawasiliano ya muuzaji?","answer":"Unaweza kuona mawasiliano aliyotoa muuzaji na kuthibitisha naye moja kwa moja modeli, vipimo, bei, hisa, muda wa kuwasilisha, masharti ya biashara, namna ya kulipa na taarifa za usafirishaji nje. Ununuzi unategemea nukuu ya mwisho au mkataba wa ununuzi au mauzo uliokubaliwa na mnunuzi na muuzaji."},{"question":"Bei inayoonyeshwa ndiyo bei ya mwisho?","answer":"Si lazima. Bei za AUTOLINK ni mwongozo wa ununuzi. Bei ya mwisho inaweza kutegemea modeli, vipimo, rangi, idadi, hisa, viwango vya fedha, sera za mtengenezaji, bandari ya kusafirisha, gharama za usafirishaji na hali ya soko. Omba nukuu rasmi ya sasa kabla ya kununua."},{"question":"Nukuu ya bei ikiisha muda wake itakuwaje?","answer":"Muuzaji anaweza kuhitaji kuthibitisha tena bei. Nukuu iliyoisha muda inaweza kufichwa au kuwekewa alama. Kuisha kwa nukuu ya gari moja hakumalizi uanachama wako."},{"question":"Taarifa za hisa ni za wakati halisi?","answer":"Si lazima. Hisa hubadilika kutokana na manunuzi mengine, uhamisho kati ya maduka, sera za mtengenezaji, mipango ya kuuza nje au mabadiliko ya mwaka wa modeli. Thibitisha upatikanaji halisi kabla ya kulipa."},{"question":"Kila gari linaweza kupelekwa nchini mwangu?","answer":"Hapana. Sheria za uagizaji, viwango vya hewa chafu, uthibitishaji wa gari, upande wa usukani, kikomo cha umri, kodi na idhini ya modeli hutofautiana kwa nchi. Angalia masharti ya nchi lengwa kabla ya kununua."},{"question":"Je, vipimo vya magari ni sahihi kabisa?","answer":"AUTOLINK hujitahidi kuweka taarifa sahihi, lakini modeli ileile inaweza kutofautiana kwa soko, mwaka na toleo. Thibitisha vipimo vya mwisho kwa karatasi ya muuzaji, taarifa za VIN na mkataba wa ununuzi."}]},"supplier":{"title":"Wauzaji","items":[{"question":"‘Muuzaji Aliyethibitishwa’ maana yake nini?","answer":"Kwa mujibu wa sheria zake, AUTOLINK inaweza kukagua majina ya kampuni, taarifa za usajili, leseni za biashara, mawasiliano, taarifa za msingi za shughuli na rasilimali za baadhi ya wauzaji. Waliokamilisha ukaguzi husika wanaweza kuonyeshwa alama ya ‘Muuzaji Aliyethibitishwa’."},{"question":"Uhakiki unamaanisha AUTOLINK inahakikisha muamala?","answer":"Hapana. Unaonyesha tu kuwa baadhi ya taarifa zilizopatikana wakati huo zilikaguliwa. Si dhamana ya uaminifu wa muuzaji, hisa, bei, utekelezaji, ubora wa gari, usalama wa malipo, muda wa usafirishaji au matokeo ya muamala."},{"question":"Nifanye nini nisipompata muuzaji?","answer":"Baada ya kufungua mawasiliano, ripoti kwa AUTOLINK ikiwa hajibu kwa muda mrefu, mawasiliano hayafanyi kazi au taarifa za gari zinatofautiana sana na tangazo. Jukwaa linaweza kukagua taarifa au kuchukua hatua kuhusu akaunti kulingana na hali."},{"question":"Nifanye nini nikigundua muuzaji wa ulaghai?","answer":"Toa ripoti kupitia jukwaa au wasiliana na usaidizi. Ikiwezekana, toa jina la muuzaji, kiungo cha gari, mazungumzo, nukuu na ushahidi mwingine. AUTOLINK inaweza kukagua, kuzuia au kufuta akaunti inayoshukiwa kwa mujibu wa sheria za jukwaa."}]},"transaction":{"title":"Miamala na malipo","items":[{"question":"AUTOLINK inapokea malipo ya magari?","answer":"Huduma ya sasa ya uanachama haikusanyi fedha za kununua magari wala kuzishikilia kama escrow. Kwa kawaida mnunuzi na muuzaji hulipana moja kwa moja kwa mkataba wao. Isiposemwa wazi kwenye ukurasa wa huduma fulani, usitume fedha za gari kwenye akaunti ya ada ya uanachama ya AUTOLINK."},{"question":"Ada ya uanachama ni amana ya gari?","answer":"Hapana. Inalipia huduma ya uanachama pekee; si amana au malipo ya gari, dhamana ya muuzaji, gharama ya usafirishaji au forodha, wala malipo ya awali. Kulipa uanachama hakuundi oda ya gari moja kwa moja."},{"question":"AUTOLINK inatoza kamisheni ya mauzo ya magari?","answer":"Kwa sasa mapato yake makuu ni ada ya uanachama. Isipoelezwa vinginevyo, kuona magari au kuwasiliana na muuzaji hakutoi kamisheni kiotomatiki. Ada za huduma zozote za baadaye za uwakala wa ununuzi, usafirishaji nje, ukaguzi, usafirishaji au nyinginezo zitaelezwa kabla ya matumizi."},{"question":"Naweza kununua gari moja kwa moja kwenye AUTOLINK?","answer":"Kwa sasa AUTOLINK huunganisha taarifa za biashara ya magari na washiriki wa mnyororo wa ugavi. Kuwasiliana na muuzaji, kuomba nukuu au kutuma swali husaidia kuanzisha mawasiliano; hakumalizi ununuzi. Muamala rasmi hutegemea mkataba wa mnunuzi na muuzaji."},{"question":"Mgogoro wa muamala ukitokea itakuwaje?","answer":"Mkataba wa gari kwa kawaida huwa kati ya mnunuzi na muuzaji, hivyo mgogoro ushughulikiwe kwanza kwa masharti yao. AUTOLINK inaweza kusaidia kukagua akaunti, kuwasiliana na muuzaji au kushughulikia ukiukaji wa jukwaa, lakini haichukui wajibu wa kimkataba wa upande wowote bila makubaliano ya wazi."}]},"account":{"title":"Akaunti na data","items":[{"question":"Watu kadhaa wanaweza kushiriki akaunti moja ya uanachama?","answer":"Kwa kawaida uanachama ni wa mwenye akaunti aliyesajiliwa au wafanyakazi walioidhinishwa wa kampuni iliyosajiliwa. Kuuza, kukodisha, kushiriki kwa wingi akaunti na kukusanya data kwa wingi kwa programu za kiotomatiki ni marufuku."},{"question":"Naweza kuhamisha mawasiliano ya wauzaji kwa wingi?","answer":"Unaweza kuona na kuhifadhi taarifa unazohitaji kwa ununuzi ndani ya mipaka ya jukwaa. Bila ruhusa ya AUTOLINK, huwezi kukusanya au kuhamisha hifadhidata ya wauzaji kwa wingi, kuiuza, kuisambaza hadharani au kuitumia kuunda hifadhidata shindani."},{"question":"Taarifa zangu zitapelekwa kwa wauzaji?","answer":"Unapotuma swali, kuwasiliana na muuzaji au kuomba nukuu, AUTOLINK inaweza kumpa taarifa zinazohitajika kujibu, kama jina, kampuni, nchi au eneo, email, simu, WhatsApp na mahitaji ya ununuzi. Sera ya faragha ina maelezo zaidi."},{"question":"AUTOLINK ni dalali au muuzaji wa magari?","answer":"AUTOLINK ni jukwaa la taarifa za biashara ya magari na uunganishaji wa mnyororo wa ugavi. Isiposemwa wazi kuwa AUTOLINK ndiye muuzaji kwenye ukurasa husika, si muuzaji wa magari yanayoonyeshwa. Muuzaji ni kampuni iliyotajwa kwenye mkataba wa ununuzi."}]}},"policies":{"terms":"Masharti ya Huduma","membershipTerms":"Masharti ya Uanachama","privacy":"Sera ya Faragha","refund":"Sera ya Marejesho"},"application":{"cta":"Tuma ombi sasa","enterpriseCta":"Ulizia mpango wa kampuni","title":"Ombi la uanachama","selected":"Mpango uliochaguliwa","message":"Malipo ya mtandaoni bado hayapatikani. Tuma barua pepe kwa AUTOLINK ukitaja mpango uliochagua na email ya akaunti yako. Tutawasiliana nawe kuhusu hatua zinazofuata. Hakuna malipo wala uanzishaji wa uanachama kwenye ukurasa huu.","send":"Tuma ombi kwa email","emailLabel":"Email ya mawasiliano","note":"Programu yako ya email itafunguka. Ombi litatumwa tu baada ya kutuma ujumbe."}}};
